#include "readers.h"
#include <stdatomic.h>
#include <stdio.h>
#include <string.h>
#define CHECK(x) do{if(!(x)){fprintf(stderr,"SR_CHECK line%d: %s\n",__LINE__,#x);return 1;}}while(0)
struct store_image {uint8_t pages[67][4096];unsigned reads,writes,flushes;int failread,failwrite;};
static struct store_image image;static struct sr_hub hub;
static int rd(void *p,uint32_t id,void *out){struct store_image *d=p;d->reads++;if(d->failread||id>=67)return 1;memcpy(out,d->pages[id],4096);return 0;}
static int wr(void *p,uint32_t id,const void *in){struct store_image *d=p;d->writes++;if(d->failwrite||id>=67)return 1;memcpy(d->pages[id],in,4096);return 0;}
static int fl(void *p){struct store_image *d=p;d->flushes++;return 0;}
static int start(void){memset(&image,0,sizeof image);store_io io={&image,rd,wr,fl,67};store s;uint8_t key=1,value=0;CHECK(store_format(io)==STORE_OK&&store_open(&s,io)==STORE_OK&&store_begin(&s)==STORE_OK&&store_put(&s,&key,1,&value,1)==STORE_OK&&store_commit(&s)==STORE_OK&&store_checkpoint(&s)==STORE_OK);CHECK(sr_init(&hub,io,7)==SR_OK);return 0;}
static int get(struct sr_lease l,int expected){uint8_t key=1,out=0xa5;size_t n=777;CHECK(sr_snapshot_get(l,&key,1,&out,1,&n)==SR_OK&&n==1&&out==expected);return 0;}
static int publish(unsigned value){uint8_t key=1,v=(uint8_t)value;return sr_publish(&hub,&key,1,&v,1);}
static int live(unsigned expected){uint8_t key=1,value=0xa5;size_t n=777;CHECK(sr_get(&hub,&key,1,&value,1,&n)==SR_OK&&n==1&&value==expected);return 0;}
static int done(void){CHECK(sr_close(&hub)==SR_OK&&sr_destroy(&hub)==SR_OK);return 0;}
static int snapshots(void){CHECK(start()==0);struct sr_lease a,b,out={0};CHECK(sr_capture(&hub,&a)==SR_OK&&get(a,0)==0);CHECK(publish(1)==SR_OK&&live(1)==0&&sr_capture(&hub,&b)==SR_OK);unsigned reads=image.reads;struct sr_lease before=out;CHECK(sr_capture(&hub,&out)==STORE_FULL&&memcmp(&out,&before,sizeof out)==0&&image.reads==reads);CHECK(publish(2)==SR_OK&&get(a,0)==0&&get(b,1)==0);CHECK(sr_release(a)==SR_OK&&sr_capture(&hub,&out)==SR_OK&&get(out,2)==0);uint8_t key=1,value=99;size_t n=777;CHECK(sr_snapshot_get(a,&key,1,&value,1,&n)==SR_STALE&&value==99&&n==777&&sr_release(a)==SR_STALE);CHECK(sr_release(b)==SR_OK&&sr_release(out)==SR_OK&&done()==0);puts("SR snapshots validated retained-and-reclaimed");return 0;}
static int shared(void){CHECK(start()==0);CHECK(hub.writer.io.ctx==&hub&&hub.reader.io.ctx==&hub&&hub.writer.io.read==hub.reader.io.read);for(unsigned i=1;i<=6;i++){CHECK(publish(i)==SR_OK&&live(i)==0);CHECK(hub.reader.generation==hub.writer.generation&&hub.reader.generation==i+1&&hub.revision==i+1);uint8_t a[4096],b[4096];hub.writer.cache[1].valid=0;hub.reader.cache[1].valid=0;uint64_t hits=hub.cache.hits;CHECK(store_page_read(&hub.writer,1,a)==STORE_OK&&store_page_read(&hub.reader,1,b)==STORE_OK&&memcmp(a,b,4096)==0&&hub.cache.hits>hits);}CHECK(done()==0);puts("SR shared validated two-actual-handles");return 0;}
static int limits(void){CHECK(start()==0);struct sr_lease a,b;hub.slots[0].serial=UINT64_MAX-1;CHECK(sr_capture(&hub,&a)==SR_OK&&a.serial==UINT64_MAX&&sr_release(a)==SR_OK);hub.slots[1].serial=UINT64_MAX-1;CHECK(sr_capture(&hub,&b)==SR_OK&&b.slot==1&&b.serial==UINT64_MAX&&sr_release(b)==SR_OK&&sr_capture(&hub,&a)==STORE_FULL);hub.revision=UINT64_MAX;unsigned writes=image.writes;CHECK(publish(7)==STORE_FULL&&image.writes==writes&&live(0)==0&&done()==0);puts("SR limits validated nonwrapping-cleanup");return 0;}
static int failure(void){CHECK(start()==0);struct sr_lease a,out={0};CHECK(sr_capture(&hub,&a)==SR_OK);for(unsigned i=0;i<4;i++)hub.reader.cache[i].valid=0;CHECK(sc_init(&hub.cache,SC_TWO_WAY)==STORE_OK);image.failread=1;struct sr_lease before=out;CHECK(sr_capture(&hub,&out)==STORE_IO&&memcmp(&out,&before,sizeof out)==0&&hub.slots[1].live==0);image.failread=0;image.failwrite=1;CHECK(publish(9)==STORE_IO&&hub.poisoned&&get(a,0)==0);uint8_t key=1,value=99;size_t n=777;CHECK(sr_get(&hub,&key,1,&value,1,&n)==STORE_STATE&&value==99&&n==777);CHECK(sr_close(&hub)==SR_BUSY&&sr_capture(&hub,&out)==SR_CLOSED&&get(a,0)==0&&sr_destroy(&hub)==STORE_STATE);CHECK(sr_release(a)==SR_OK&&done()==0);puts("SR failure validated copies-survive-poison-close");return 0;}
static atomic_int ready,startflag;static int writer_error,reader_error;
static void wait_start(void){atomic_fetch_add_explicit(&ready,1,memory_order_release);while(!atomic_load_explicit(&startflag,memory_order_acquire)){} }
static void *writer(void *ctx){(void)ctx;wait_start();for(unsigned i=1;i<=32;i++)if(publish(i)!=SR_OK)writer_error=1;return NULL;}
static void *reader(void *ctx){struct sr_lease l=*(struct sr_lease *)ctx;wait_start();unsigned previous=0;for(unsigned i=0;i<128;i++){uint8_t key=1,value=0;size_t n=0;int r=sr_get(&hub,&key,1,&value,1,&n);if(r||n!=1||value<previous||value>32||get(l,0))reader_error=1;previous=value;}return NULL;}
static int threaded(void){CHECK(start()==0);struct sr_lease old;CHECK(sr_capture(&hub,&old)==SR_OK);atomic_init(&ready,0);atomic_init(&startflag,0);writer_error=reader_error=0;pthread_t a,b;CHECK(pthread_create(&a,NULL,writer,NULL)==0&&pthread_create(&b,NULL,reader,&old)==0);while(atomic_load_explicit(&ready,memory_order_acquire)!=2){}atomic_store_explicit(&startflag,1,memory_order_release);CHECK(pthread_join(a,NULL)==0&&pthread_join(b,NULL)==0&&!writer_error&&!reader_error&&live(32)==0&&get(old,0)==0);CHECK(sr_release(old)==SR_OK&&done()==0);puts("SR threaded validated joined-writer-reader");return 0;}
static int oracle(void){unsigned reset,op;int initialized=0;struct sr_lease tokens[2]={{0}};int owned[2]={0};while(scanf("%u %u",&reset,&op)==2){if(reset){if(initialized){for(unsigned i=0;i<2;i++)if(owned[i])CHECK(sr_release(tokens[i])==SR_OK);CHECK(done()==0);}CHECK(start()==0);initialized=1;owned[0]=owned[1]=0;}int result=0;if(op<2)result=publish(op+1);else if(op==2){struct sr_lease out={0};result=sr_capture(&hub,&out);if(!result){tokens[out.slot]=out;owned[out.slot]=1;}}else if(op==3){unsigned slot=0;while(slot<2&&!owned[slot])slot++;if(slot==2)result=STORE_NOT_FOUND;else{result=sr_release(tokens[slot]);if(!result)owned[slot]=0;}}else if(op==4)result=sr_close(&hub);else{uint8_t key=1,value=0;size_t n=0;result=sr_get(&hub,&key,1,&value,1,&n);}uint8_t key=1,value=0;size_t n=0;int r=sr_get(&hub,&key,1,&value,1,&n);int livevalue=r?-r:value;printf("%d %d",result,livevalue);for(unsigned i=0;i<2;i++){int v=-1;if(owned[i]){CHECK(sr_snapshot_get(tokens[i],&key,1,&value,1,&n)==SR_OK);v=value;}printf(" %d",v);}putchar('\n');}if(initialized){for(unsigned i=0;i<2;i++)if(owned[i])CHECK(sr_release(tokens[i])==SR_OK);CHECK(done()==0);}return 0;}
int main(int argc,char **argv){if(argc!=2)return 2;if(!strcmp(argv[1],"snapshots"))return snapshots();if(!strcmp(argv[1],"shared"))return shared();if(!strcmp(argv[1],"limits"))return limits();if(!strcmp(argv[1],"failure"))return failure();if(!strcmp(argv[1],"threaded"))return threaded();if(!strcmp(argv[1],"oracle"))return oracle();return 2;}
